 public sealed class InputRoundCard055:System.Windows.Forms.Panel {
  public InputRoundCard055(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);}
  protected override void OnPaintBackground(PaintEventArgs e){e.Graphics.Clear(Parent==null?SystemColors.Control:Parent.BackColor);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;int d=24;using(var p=new GraphicsPath()){p.AddArc(0,0,d,d,180,90);p.AddArc(Width-d-1,0,d,d,270,90);p.AddArc(Width-d-1,Height-d-1,d,d,0,90);p.AddArc(0,Height-d-1,d,d,90,90);p.CloseFigure();using(var b=new SolidBrush(BackColor))e.Graphics.FillPath(b,p);}}
 }
 public sealed class InputRoundButton055:Button {
  protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(Parent==null?SystemColors.Control:Parent.BackColor);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;int d=16;using(var p=new GraphicsPath()){p.AddArc(0,0,d,d,180,90);p.AddArc(Width-d-1,0,d,d,270,90);p.AddArc(Width-d-1,Height-d-1,d,d,0,90);p.AddArc(0,Height-d-1,d,d,90,90);p.CloseFigure();using(var b=new SolidBrush(Enabled?BackColor:SystemColors.ControlDark))e.Graphics.FillPath(b,p);}TextRenderer.DrawText(e.Graphics,Text,Font,ClientRectangle,ForeColor,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);if(Focused)ControlPaint.DrawFocusRectangle(e.Graphics,new Rectangle(5,5,Width-10,Height-10));}
 }
 public sealed partial class FloorsUi054 {
  DataGridView heights;Label heightScope;bool refreshingHeights;string editingRoom;TextBox activeHeightEditor;
  static void RoundSurface(Control c,int radius){Action shape=delegate{if(c.Width<radius*2||c.Height<radius*2)return;using(var p=new GraphicsPath()){int d=radius*2;p.AddArc(0,0,d,d,180,90);p.AddArc(c.Width-d,0,d,d,270,90);p.AddArc(c.Width-d,c.Height-d,d,d,0,90);p.AddArc(0,c.Height-d,d,d,90,90);p.CloseFigure();var old=c.Region;c.Region=new Region(p);if(old!=null)old.Dispose();}};c.SizeChanged+=delegate{shape();};shape();}
  TabPage BuildHeights(){
   var tab=new TabPage("CAO ĐỘ THIẾT BỊ"){BackColor=Color.FromArgb(240,245,249),Padding=new Padding(7)};
   heightScope=new Label{Dock=DockStyle.Top,Height=40,ForeColor=Color.FromArgb(24,102,119)};
   var bar=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=34};bar.Controls.Add(MakeButton("+ LOẠI",delegate{DeviceDialog(false);}));bar.Controls.Add(MakeButton("ĐỔI TÊN",delegate{DeviceDialog(true);}));bar.Controls.Add(MakeButton("XÓA LOẠI",DeleteDevice));bar.Controls.Add(MakeButton("DÙNG CHUNG",UseCommon));
   heights=new DataGridView{Dock=DockStyle.Fill,BackgroundColor=Color.White,BorderStyle=BorderStyle.None,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AllowUserToResizeRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,SelectionMode=DataGridViewSelectionMode.CellSelect,MultiSelect=false,EnableHeadersVisualStyles=false};
   heights.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(231,240,244);heights.ColumnHeadersDefaultCellStyle.ForeColor=Color.FromArgb(24,60,70);heights.ColumnHeadersHeight=34;heights.ColumnHeadersDefaultCellStyle.WrapMode=DataGridViewTriState.True;heights.ColumnHeadersDefaultCellStyle.Alignment=DataGridViewContentAlignment.MiddleCenter;heights.DefaultCellStyle.Alignment=DataGridViewContentAlignment.MiddleCenter;heights.RowTemplate.Height=23;
   heights.ColumnHeadersDefaultCellStyle.Font=new Font(Font,FontStyle.Bold);heights.ColumnHeadersBorderStyle=DataGridViewHeaderBorderStyle.None;heights.CellBorderStyle=DataGridViewCellBorderStyle.SingleHorizontal;heights.GridColor=Color.FromArgb(227,234,240);heights.DefaultCellStyle.SelectionBackColor=Color.FromArgb(206,233,239);heights.DefaultCellStyle.SelectionForeColor=Color.FromArgb(24,60,70);heights.AlternatingRowsDefaultCellStyle.BackColor=Color.FromArgb(249,251,253);heights.DefaultCellStyle.Padding=new Padding(4,1,4,1);
   heights.Columns.Add("device","LOẠI THIẾT BỊ");heights.Columns.Add("common","CHUNG\n(M)");heights.Columns.Add("room","RIÊNG\n(M)");heights.Columns.Add("effective","ÁP DỤNG\n(M)");heights.Columns.Add("origin","THIẾT LẬP");
   heights.Columns[0].FillWeight=160;heights.Columns[4].FillWeight=120;heights.Columns[3].HeaderCell.ToolTipText="CAO ĐỘ THỰC TẾ: ƯU TIÊN GIÁ TRỊ RIÊNG CỦA PHÒNG; NẾU ĐỂ TRỐNG THÌ LẤY CHUNG.";heights.Columns[4].HeaderCell.ToolTipText="CHO BIẾT CAO ĐỘ ĐANG LẤY TỪ THÔNG SỐ CHUNG HAY ĐẶT RIÊNG CHO PHÒNG.";heights.Columns[0].ReadOnly=true;heights.Columns[3].ReadOnly=true;heights.Columns[4].ReadOnly=true;
   foreach(DataGridViewColumn col in heights.Columns)col.SortMode=DataGridViewColumnSortMode.NotSortable;
   heights.EditingControlShowing+=delegate(object sender,DataGridViewEditingControlShowingEventArgs e){if(activeHeightEditor!=null)activeHeightEditor.TextChanged-=PreviewHeight;activeHeightEditor=e.Control as TextBox;if(activeHeightEditor!=null){activeHeightEditor.TextChanged+=PreviewHeight;PreviewHeight(activeHeightEditor,EventArgs.Empty);}};
   heights.CellValidating+=delegate(object sender,DataGridViewCellValidatingEventArgs e){if(refreshingHeights||e.RowIndex<0||(e.ColumnIndex!=1&&e.ColumnIndex!=2))return;try{string txt=Convert.ToString(e.FormattedValue);if(txt.Trim().Length>0&&Floors054.Number(txt)<0)throw new InvalidOperationException("Cao độ phải không âm.");heights.Rows[e.RowIndex].ErrorText="";}catch(Exception ex){e.Cancel=true;heights.Rows[e.RowIndex].ErrorText=ex.Message;status.Text=ex.Message;status.ForeColor=Color.Firebrick;}};
   heights.CellEndEdit+=delegate(object sender,DataGridViewCellEventArgs e){if(refreshingHeights||e.RowIndex<0)return;Run(delegate{var row=heights.Rows[e.RowIndex];string txt=Convert.ToString(row.Cells[e.ColumnIndex].Value);decimal? value=string.IsNullOrWhiteSpace(txt)?(decimal?)null:Floors054.Number(txt);data.SetHeight((string)row.Tag,e.ColumnIndex==2?editingRoom:null,value);RefreshHeights();});};
   heights.DataError+=delegate(object sender,DataGridViewDataErrorEventArgs e){e.ThrowException=false;status.Text="Kiểm tra lại số M trong ô đang sửa.";};
   var card=new InputRoundCard055{Dock=DockStyle.Fill,BackColor=Color.White,Padding=new Padding(7)};card.Controls.Add(heights);RoundSurface(card,12);tab.Controls.Add(card);tab.Controls.Add(bar);tab.Controls.Add(heightScope);return tab;
  }
  void PreviewHeight(object sender,EventArgs args){
   if(refreshingHeights||activeHeightEditor==null||heights.CurrentCell==null||!heights.IsCurrentCellInEditMode)return;
   int col=heights.CurrentCell.ColumnIndex;if(col!=1&&col!=2)return;var row=heights.CurrentRow;if(row==null||row.Tag==null)return;
   try{string txt=activeHeightEditor.Text.Trim();decimal? input=txt.Length==0?(decimal?)null:Floors054.Number(txt);if(input<0)throw new InvalidOperationException();
    var definition=data.devices.Single(x=>x.id==(string)row.Tag);decimal? value=col==1?input:input??definition.height;bool own=col==2&&input.HasValue;
    row.Cells[3].Value=value.HasValue?value.Value.ToString("0.###"):"—";row.Cells[4].Value=!value.HasValue?"CHƯA NHẬP":own?"RIÊNG PHÒNG":"DÙNG CHUNG";
    row.Cells[4].Style.ForeColor=!value.HasValue?Color.Firebrick:own?Color.DarkOrange:Color.Teal;
   }catch{row.Cells[3].Value="—";row.Cells[4].Value="KIỂM TRA";row.Cells[4].Style.ForeColor=Color.Firebrick;}
  }
  void RefreshHeights(){if(heights==null||loading)return;refreshingHeights=true;try{string room=RoomId();string selected=heights.CurrentRow==null?null:heights.CurrentRow.Tag as string;heights.Rows.Clear();Room054 r=room==null?null:data.floors.SelectMany(f=>f.rooms).Single(x=>x.id==room);heightScope.Text=r==null?"THÔNG SỐ CHUNG · ÁP DỤNG CHO CÁC PHÒNG\nNHẬP MỘT LẦN CHO TOÀN BỘ PHÒNG. Ô TRỐNG = CHƯA KHAI BÁO.":"PHÒNG: "+r.name.ToUpperInvariant()+"\nNHẬP CỘT RIÊNG CHO PHÒNG NÀY. ĐỂ TRỐNG = DÙNG CHUNG.";
   editingRoom=room;heights.Columns[1].ReadOnly=r!=null;heights.Columns[2].ReadOnly=r==null;heights.Columns[2].Visible=r!=null;
   foreach(var d in data.devices){decimal h;bool own=r!=null&&r.heights.TryGetValue(d.id,out h);var effective=data.Height(d.id,room);int i=heights.Rows.Add(d.name.ToUpperInvariant(),d.height.HasValue?d.height.Value.ToString("0.###"):"",own?r.heights[d.id].ToString("0.###"):"",effective.HasValue?effective.Value.ToString("0.###"):"—",!effective.HasValue?"CHƯA NHẬP":own?"RIÊNG PHÒNG":"DÙNG CHUNG");var row=heights.Rows[i];row.Tag=d.id;row.Cells[r==null?1:2].Style.BackColor=Color.FromArgb(239,247,251);row.Cells[4].Style.ForeColor=!effective.HasValue?Color.Firebrick:own?Color.DarkOrange:Color.Teal;if(d.id==selected)heights.CurrentCell=row.Cells[0];}
  }finally{refreshingHeights=false;}}
  void DeviceDialog(bool rename){Run(delegate{var current=heights.CurrentRow;string id=current==null?null:current.Tag as string;if(rename&&id==null)throw new InvalidOperationException("Chọn loại cần đổi tên.");using(var f=new Form{Text=rename?"ĐỔI TÊN LOẠI THIẾT BỊ":"THÊM LOẠI THIẾT BỊ",ClientSize=new Size(410,150),StartPosition=FormStartPosition.CenterParent,Font=Font}){var input=new TextBox{Left=18,Top=45,Width=370,Text=rename?data.devices.Single(x=>x.id==id).name:""};f.Controls.Add(new Label{Left=18,Top=15,Width=370,Text="TÊN LOẠI (VÍ DỤ: ĐÈN LED DÂY)"});f.Controls.Add(input);var ok=MakeButton("ÁP DỤNG",delegate{try{var c=data.Clone();if(rename)c.devices.Single(x=>x.id==id).name=input.Text.Trim();else c.devices.Add(new DeviceHeight055{name=input.Text.Trim()});c.Validate();data=c;f.DialogResult=DialogResult.OK;}catch(Exception ex){MessageBox.Show(f,ex.Message,"Kiểm tra dữ liệu");}});ok.Location=new Point(260,100);f.Controls.Add(ok);f.AcceptButton=ok;RoundSurface(f,12);if(f.ShowDialog(this)==DialogResult.OK)RefreshHeights();}});}
  void DeleteDevice(){Run(delegate{if(heights.CurrentRow==null)return;string id=(string)heights.CurrentRow.Tag;string name=data.devices.Single(x=>x.id==id).name;int count=data.floors.SelectMany(f=>f.rooms).Count(r=>r.heights.ContainsKey(id));if(!ConfirmDelete("Xóa loại "+name+" khỏi INPUT?\nSẽ bỏ cả "+count+" cao độ riêng của loại này trong các phòng.\nKhông xóa block trên bản vẽ."))return;data.RemoveDevice(id);RefreshHeights();});}
  void UseCommon(){Run(delegate{if(RoomId()==null||heights.CurrentRow==null)throw new InvalidOperationException("Chọn phòng và loại thiết bị cần trở về thông số chung.");data.SetHeight((string)heights.CurrentRow.Tag,RoomId(),null);RefreshHeights();});}
  void SaveTemplate(){Run(delegate{if(!ValidateChildren()||!heights.EndEdit()||!CommitInputs())return;var c=data.Clone();c.datum=Floors054.Number(datum.Text);using(var dialog=new SaveFileDialog{Title="LƯU MODULE INPUT",Filter="Mẫu INPUT (*.meps-input.json)|*.meps-input.json",FileName="MODULE_INPUT.meps-input.json",OverwritePrompt=true}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;Floors054.WriteTemplate(dialog.FileName,c.Template(Path.GetFileNameWithoutExtension(dialog.FileName)));status.Text="Đã lưu mẫu: "+Path.GetFileName(dialog.FileName)+". Mẫu gồm tầng, phòng, loại thiết bị và cao độ riêng.";status.ForeColor=Color.Teal;}});}
  void OpenTemplate(){Run(delegate{using(var dialog=new OpenFileDialog{Title="MỞ MODULE INPUT",Filter="Mẫu INPUT (*.meps-input.json)|*.meps-input.json",CheckFileExists=true}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;var next=Floors054.FromTemplate(File.ReadAllText(dialog.FileName));if(MessageBox.Show(this,"Mẫu có "+next.floors.Count+" tầng, "+next.floors.Sum(f=>f.rooms.Count)+" phòng và "+next.devices.Count+" loại thiết bị.\nThay phần khai báo INPUT đang mở bằng mẫu này?\nChỉ ghi vào bản vẽ khi bấm LƯU VÀO DWG; không sửa hình vẽ.","ÁP DỤNG MODULE",MessageBoxButtons.OKCancel,MessageBoxIcon.Question)!=DialogResult.OK)return;data=next;RefreshTree(0,null);status.Text="Đã mở mẫu. Chỉnh thông số cần thiết rồi LƯU VÀO DWG.";status.ForeColor=Color.Teal;}});}
 }
